import hashlib, json, os, stat, sys
manifest_path=sys.argv[1]
m=json.load(open(manifest_path)); root=os.path.join(os.path.dirname(manifest_path),m['workspace'])
expected={r['path']:r for r in m['entries']}
actual={}
for base,dirs,files in os.walk(root,followlinks=False):
    for name in list(dirs):
        p=os.path.join(base,name); rel=os.path.relpath(p,os.path.dirname(manifest_path)).replace(os.sep,'/')
        if os.path.islink(p): actual[rel]=('symlink',os.readlink(p)); dirs.remove(name)
        else: actual[rel]=('directory',None)
    for name in files:
        p=os.path.join(base,name); rel=os.path.relpath(p,os.path.dirname(manifest_path)).replace(os.sep,'/')
        if os.path.islink(p): actual[rel]=('symlink',os.readlink(p))
        elif os.path.isfile(p):
            h=hashlib.sha256()
            with open(p,'rb') as f:
                for chunk in iter(lambda:f.read(1024*1024),b''):h.update(chunk)
            actual[rel]=('file',h.hexdigest())
        else: actual[rel]=('other',None)
missing=sorted(set(expected)-set(actual)); extra=sorted(set(actual)-set(expected)); changed=[]
for rel in sorted(set(expected)&set(actual)):
    r=expected[rel]; kind,val=actual[rel]
    if kind!=r['kind'] or (kind=='file' and val!=r.get('sha256')) or (kind=='symlink' and val!=r.get('target')):
        changed.append({'path':rel,'expected_kind':r['kind'],'actual_kind':kind,'expected_sha256':r.get('sha256'),'actual_sha256_or_target':val})
allowed={f'content/workspace/.git/annex/keysdb/{x}' for x in ('db','db-shm','db-wal')}
metadata=[x for x in changed if x['path'] in allowed and x['actual_kind']=='file']
changed_integrity=[x for x in changed if x not in metadata]
