extra_integrity=[x for x in extra if x not in extra_metadata]
print(json.dumps({'manifest_sha256':hashlib.sha256(open(manifest_path,'rb').read()).hexdigest(),'missing':missing,'extra_integrity':extra_integrity,'changed_integrity':changed_integrity,'operational_metadata_changed':metadata,'operational_metadata_added':extra_metadata},indent=2))
