import hashlib, json, os, stat, sys
mp=sys.argv[1]; bundle=os.path.dirname(mp); m=json.load(open(mp)); expected={r['path']:r for r in m['entries']}; expected.update({'manifest.json':{'kind':'file','sha256':hashlib.sha256(open(mp,'rb').read()).hexdigest()}})
for name,mode in m.get('container_modes',{}).items():
    if name!='manifest.json': expected[name]={'kind':'directory'}
actual={}
for base,dirs,files in os.walk(bundle,followlinks=False):
    for n in list(dirs):
        p=os.path.join(base,n); rel=os.path.relpath(p,bundle).replace(os.sep,'/')
        if os.path.islink(p): actual[rel]=('symlink',os.readlink(p)); dirs.remove(n)
        else: actual[rel]=('directory',None)
    for n in files:
        p=os.path.join(base,n); rel=os.path.relpath(p,bundle).replace(os.sep,'/')
        if os.path.islink(p): actual[rel]=('symlink',os.readlink(p))
        elif os.path.isfile(p):
            h=hashlib.sha256()
            with open(p,'rb') as f:
                for c in iter(lambda:f.read(1024*1024),b''):h.update(c)
            actual[rel]=('file',h.hexdigest())
        else: actual[rel]=('other',None)
missing=sorted(set(expected)-set(actual)); extra=sorted(set(actual)-set(expected)); changed=[]
for rel in sorted(set(expected)&set(actual)):
    r=expected[rel]; kind,val=actual[rel]
    mismatch=(kind!=r['kind'] or (kind=='file' and val!=r.get('sha256')) or (kind=='symlink' and val!=r.get('link_target')))
    if mismatch: changed.append({'path':rel,'expected_kind':r['kind'],'actual_kind':kind,'expected_sha256_or_target':r.get('sha256',r.get('link_target')),'actual_sha256_or_target':val})
allowed={f'content/workspace/.git/annex/keysdb/{x}' for x in ('db','db-shm','db-wal')}
def is_allowed(path,kind): return path in allowed and kind=='file'
metadata=[x for x in changed if is_allowed(x['path'],x['actual_kind'])]
extra_meta=[x for x in extra if is_allowed(x,actual[x][0])]
